     };

     const form = document.getElementById("quiz-form");
     const results = document.getElementById("quiz-results");
     const questions = Array.from(form.querySelectorAll(".form-field"));

     function getCheckedValues(questionId) {
       return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map(
         (input) => input.value
       );
     }

     function updateQuestionError(questionId, message) {
       const field = form.querySelector(`[data-question="${questionId}"]`);
       const error = document.getElementById(`${questionId}-error`);
       const firstCheckbox = form.querySelector(`input[name="${questionId}"]`);
       const hasError = Boolean(message);

       field.classList.toggle("has-error", hasError);
       error.hidden = !hasError;
       error.textContent = message || "";
       firstCheckbox.setAttribute("aria-invalid", String(hasError));
     }

     function clearQuestionError(questionId) {
       updateQuestionError(questionId, "");
     }

     questions.forEach((field) => {
       const questionId = field.dataset.question;
       const checkboxes = field.querySelectorAll('input[type="checkbox"]');

       checkboxes.forEach((checkbox) => {
         checkbox.addEventListener("change", () => {
           if (getCheckedValues(questionId).length > 0) {
             clearQuestionError(questionId);
           }
         });
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;
       let firstInvalid = null;

       Object.keys(answerKey).forEach((questionId) => {
         const selected = getCheckedValues(questionId);
         const correct = answerKey[questionId];

         if (selected.length === 0) {
           updateQuestionError(questionId, `Error: Select at least one answer for question ${questionId.slice(1)}.`);

           if (!firstInvalid) {
             firstInvalid = form.querySelector(`input[name="${questionId}"]`);
           }

           return;
         }

         clearQuestionError(questionId);

         const isCorrect =
           selected.length === correct.length &&
           selected.every((value) => correct.includes(value));

         if (isCorrect) {
           score += 1;
         }
       });

       if (firstInvalid) {
         results.hidden = true;
         firstInvalid.focus();
         return;
       }

       results.hidden = false;
       results.innerHTML = `<strong>Score: ${score} / ${Object.keys(answerKey).length}</strong><br>Correct answers:<br>1. C, Rust, Java<br>2. HTML, CSS, JavaScript<br>3. SQL, R, Python`;
     });
   </script>
 </body>
